  if(mat==='glass'){ noise(1400,1.8,'highpass',4800*J,0.7,0.07*vol,t); tone('triangle',2600*J,2500*J,0.14,0.025*vol,t+0.02); tone('triangle',3400*J,3300*J,0.11,0.02*vol,t+0.05); return true; }
